+    /// <summary>
+    /// 历史逾期数据导入服务
+    /// </summary>
+    public class HistoricalOverdueImportService : OnlyUnitWorkBaeApp
+    {
+        private readonly HistoricalOverdueCalculationService _historicalOverdueCalculationService;
+        private readonly ICustomerCommonApp _customerCommonApp;
+        private readonly IServiceProvider _serviceProvider;
+        /// <summary>
+        /// 构造函数
+        /// </summary>
+        public HistoricalOverdueImportService(
+            IUnitWork unitWork,
+            IAuth auth,
+            HistoricalOverdueCalculationService historicalOverdueCalculationService,
+            ICustomerCommonApp customerCommonApp,
+            IServiceProvider serviceProvider) : base(unitWork, auth)
