+        /// <summary>
+        /// 导入历史逾期数据（日期范围）
+        /// </summary>
+        /// <param name="startDate">开始日期</param>
+        /// <param name="endDate">结束日期</param>
+        /// <param name="batchSize">每批处理订单数量</param>
+        public async Task ImportHistoricalOverdueDataByRange(DateTime startDate, DateTime endDate, int batchSize = 100)
+        {
+            try
+            {
+                LogHelper.Info($"开始导入{startDate:yyyy-MM-dd}至{endDate:yyyy-MM-dd}的历史逾期数据", nameof(HistoricalOverdueImportService), nameof(ImportHistoricalOverdueDataByRange));
+
+                // 查询所有已收款完成但历史有过逾期的订单
+                var completedOrders = await GetCompletedOrdersWithHistoricalOverdue();
+                LogHelper.Info($"共查询到{completedOrders.Count}个符合条件的订单", nameof(HistoricalOverdueImportService), nameof(ImportHistoricalOverdueDataByRange));
+                // 分批处理订单
+                for (int i = 0; i < completedOrders.Count; i += batchSize)
+                {
+                   var batchOrders = completedOrders.Skip(i).Take(batchSize).ToList();
+                   await ProcessOrderBatchByRange(batchOrders, endDate);
+                   LogHelper.Info($"已处理{i + batchOrders.Count}/{completedOrders.Count}个订单", nameof(HistoricalOverdueImportService), nameof(ImportHistoricalOverdueDataByRange));
+                }
+              
+                LogHelper.Info($"历史逾期数据范围导入完成", nameof(HistoricalOverdueImportService), nameof(ImportHistoricalOverdueDataByRange));
+            }
+            catch (Exception ex)
+            {
+                LogHelper.Error(ex, $"导入历史逾期数据失败", nameof(HistoricalOverdueImportService), nameof(ImportHistoricalOverdueDataByRange));
+                throw;
+            }
+        }
+
+        /// <summary>
+        /// 将订单列表划分为多个批次
+        /// </summary>
+        /// <param name="orders">订单列表</param>
+        /// <param name="batchSize">每批订单数量</param>
+        /// <returns>批次列表</returns>
+        private static List<List<ORDR>> PartitionBatches(List<ORDR> orders, int batchSize)
+        {
+            var batches = new List<List<ORDR>>();
+            
+            for (int i = 0; i < orders.Count; i += batchSize)
+            {
+                var batch = orders.Skip(i).Take(batchSize).ToList();
+                batches.Add(batch);
+            }
+            
+            return batches;
+        }
+
+        /// <summary>
+        /// 导入历史逾期数据（日期范围）- 并行版本
+        /// </summary>
+        /// <param name="endDate">结束日期</param>
+        /// <param name="batchSize">每批处理订单数量</param>
+        /// <param name="maxDegreeOfParallelism">最大并行度</param>
+        /// <returns>并行处理结果</returns>
+        public async Task<ParallelProcessingResult> ImportHistoricalOverdueDataByRangeParallel(
+            DateTime endDate, 
+            int batchSize = 1000, 
+            int maxDegreeOfParallelism = 4)
+        {
+            var stopwatch = System.Diagnostics.Stopwatch.StartNew();
+            var result = new ParallelProcessingResult();
+            var lockObj = new object();
+            var failedBatches = new List<(long batchIndex, Exception exception)>();
+            var lastProgressLogTime = DateTime.MinValue;
+            const int progressLogIntervalSeconds = 30;
+
+            try
+            {
+                LogHelper.Info($"[并行] 开始导入至{endDate:yyyy-MM-dd}的历史逾期数据，批次大小：{batchSize}，最大并行度：{maxDegreeOfParallelism}", nameof(HistoricalOverdueImportService), nameof(ImportHistoricalOverdueDataByRangeParallel));
+
+                var completedOrders = await GetCompletedOrdersWithHistoricalOverdue();
+                result.TotalOrders = completedOrders.Count;
+
+                LogHelper.Info($"[并行] 共查询到{completedOrders.Count}个符合条件的订单", nameof(HistoricalOverdueImportService), nameof(ImportHistoricalOverdueDataByRangeParallel));
+
+                if (completedOrders.Count == 0)
+                {
+                    stopwatch.Stop();
+                    result.TotalMilliseconds = stopwatch.ElapsedMilliseconds;
+                    LogHelper.Info($"[并行] 没有订单需要处理，直接返回", nameof(HistoricalOverdueImportService), nameof(ImportHistoricalOverdueDataByRangeParallel));
+                    return result;
+                }
+
+                var batches = PartitionBatches(completedOrders, batchSize);
+
+                result.TotalBatches = batches.Count;
+
+                LogHelper.Info($"[并行] 已将订单划分为{batches.Count}个批次", nameof(HistoricalOverdueImportService), nameof(ImportHistoricalOverdueDataByRangeParallel));
+
+                var parallelOptions = new ParallelOptions 
+                { 
+                    MaxDegreeOfParallelism = maxDegreeOfParallelism 
+                };
+
+                await Task.Run(() => 
+                {
+                    Parallel.ForEach(
+                        batches, 
+                        parallelOptions, 
+                        (batch, state, batchIndex) => 
+                        {
+                            using (var scope = _serviceProvider.CreateScope())
+                            {
+                                try
+                                {
+                                    var scopedUnitWork = scope.ServiceProvider.GetRequiredService<IUnitWork>();
+                                    var scopedCustomerCommonApp = scope.ServiceProvider.GetRequiredService<ICustomerCommonApp>();
+                                    var scopedHistoricalCalculationService = scope.ServiceProvider.GetRequiredService<HistoricalOverdueCalculationService>();
+
+                                    ProcessOrderBatchByRangeInternal(
+                                        scopedUnitWork,
+                                        scopedCustomerCommonApp,
+                                        scopedHistoricalCalculationService,
+                                        batch,
+                                        endDate).GetAwaiter().GetResult();
+
+                                    lock (lockObj)
+                                    {
+                                        result.SuccessBatches++;
+                                        result.SuccessOrders += batch.Count;
+                                    }
+
+                                    var now = DateTime.Now;
+                                    if ((now - lastProgressLogTime).TotalSeconds >= progressLogIntervalSeconds)
+                                    {
+                                        lock (lockObj)
+                                        {
+                                            var progress = (result.SuccessOrders * 100.0 / result.TotalOrders);
+                                            var elapsedSeconds = stopwatch.Elapsed.TotalSeconds;
+                                            var throughput = result.SuccessOrders / elapsedSeconds;
+                                            LogHelper.Info($"[并行] 进度：{result.SuccessOrders}/{result.TotalOrders} ({progress:F2}%)，耗时：{elapsedSeconds:F1}秒，吞吐量：{throughput:F2}订单/秒", nameof(HistoricalOverdueImportService), nameof(ImportHistoricalOverdueDataByRangeParallel));
+                                            lastProgressLogTime = now;
+                                        }
+                                    }
+                                }
+                                catch (Exception ex)
+                                {
+                                    lock (lockObj)
+                                    {
+                                        result.FailedBatches++;
+                                        result.FailedOrders += batch.Count;
+                                        failedBatches.Add((batchIndex, ex));
+                                    }
+                                    LogHelper.Error(ex, $"[并行] 处理批次{batchIndex}失败（包含{batch.Count}个订单）", nameof(HistoricalOverdueImportService), nameof(ImportHistoricalOverdueDataByRangeParallel));
+                                }
+                            }
+                        });
+                });
+
+
+                stopwatch.Stop();
+                result.TotalMilliseconds = stopwatch.ElapsedMilliseconds;
+
+                if (failedBatches.Any())
+                {
+                    foreach (var (batchIndex, exception) in failedBatches)
+                    {
+                        result.FailedBatchInfo.Add($"批次{batchIndex}: {exception.Message}");
+                    }
+                }
+
+                LogHelper.Info($"[并行] 历史逾期数据范围导入完成，总耗时：{stopwatch.Elapsed.TotalSeconds:F2}秒", nameof(HistoricalOverdueImportService), nameof(ImportHistoricalOverdueDataByRangeParallel));
+                LogHelper.Info($"[并行] 处理结果：成功{result.SuccessBatches}/{result.TotalBatches}批次，{result.SuccessOrders}/{result.TotalOrders}订单，失败{result.FailedBatches}/{result.TotalBatches}批次，{result.FailedOrders}/{result.TotalOrders}订单", nameof(HistoricalOverdueImportService), nameof(ImportHistoricalOverdueDataByRangeParallel));
+                LogHelper.Info($"[并行] 性能指标：吞吐量{result.GetThroughputPerSecond():F2}订单/秒，成功率{result.GetSuccessRate():F2}%", nameof(HistoricalOverdueImportService), nameof(ImportHistoricalOverdueDataByRangeParallel));
+
+                return result;
+            }
+            catch (Exception ex)
+            {
+                stopwatch.Stop();
+                result.TotalMilliseconds = stopwatch.ElapsedMilliseconds;
+                LogHelper.Error(ex, $"[并行] 导入历史逾期数据失败", nameof(HistoricalOverdueImportService), nameof(ImportHistoricalOverdueDataByRangeParallel));
+                throw;
+            }
+        }
