+        /// <param name="endDate">结束日期</param>
+        private async Task ProcessOrderBatchByRangeInternal(
+            IUnitWork unitWork,
+            ICustomerCommonApp customerCommonApp,
+            HistoricalOverdueCalculationService historicalOverdueCalculationService,
+            List<ORDR> orders,
+            DateTime endDate)
+        {
+            // ================== 批量预加载所有必要数据 (N+1 优化) ==================
+            
+            // 提取订单ID列表
+            var orderIds = orders.Select(o => o.DocEntry).ToList();
+            
+            // 1. 批量获取客户类型 (全局数据，只需要获取一次)
+            var customerTypes = await customerCommonApp.GetMainlandCustomerType();
+            
+            // 2. 批量获取罚息规则 (只有两种规则，只需要获取一次)
+            var penaltyRuleSchool = await GetApplicablePenaltyRuleInternal(unitWork, true);
+            var penaltyRuleOther = await GetApplicablePenaltyRuleInternal(unitWork, false);
+            var penaltyRules = new Dictionary<bool, PenaltyRuleDefinition>
+            {
+                { true, penaltyRuleSchool },
+                { false, penaltyRuleOther }
+            };
+            
+            // 3. 批量获取订单详情
+            var batchSaleOrders = await historicalOverdueCalculationService.GetBatchSaleOrdersInternalAsync(unitWork,orderIds);  
+            
+            // 4. 提取所有GroupNum，批量获取付款条款
+            var groupNums = batchSaleOrders.Values
+                .Where(o => o != null && o.GroupNum.HasValue)
+                .Select(o => o.GroupNum.Value)
+                .Distinct()
+                .ToList();
+            var batchPayTerms = await HistoricalOverdueCalculationService.GetBatchPayTermsInternalAsync(unitWork,groupNums);
+            
+            // 5. 批量获取发货记录
+            var batchDeliveries = await GetBatchAlreadyDeliverysInternal(unitWork, orderIds);
+
+            // 6. 批量获取收款记录
+            var batchReceipts = await GetBatchReceiptHistoryInternal(unitWork, orderIds);
+
+            // 7. 批量获取退货记录
+            var batchReturns = await GetBatchHistoricalReturnsInternal(unitWork, orderIds, endDate);
+            var batchRefunds = await GetBatchRefundHistoryInternal(unitWork, orderIds);
+
+            // 8. 批量获取清账记录
+            var batchClearRecons = await GetBatchHistoricalClearReconsInternal(unitWork, orderIds);
+
+            // 9. 批量获取销售订单插件
+            var batchSaleOrderPlugins = await GetBatchSaleOrderPluginsInternal(unitWork, orderIds);
+
+            // 10. 提取所有SlpCode，批量获取销售员信息
+            var slpCodes = orders.Where(o => o.SlpCode.HasValue)
+                .Select(o => o.SlpCode.Value)
+                .Distinct()
+                .ToList();
+            var batchSlps = await GetBatchSlpsInternal(unitWork, slpCodes);
+
+            // 提取所有相关订单的插件的关联备注（【可清单】和不可清单）
+            var batchSaleOrderRemarkCanClear = await unitWork.Find<SaleOrdrRemark>(r =>
+                orderIds.Contains(r.DocEntry) &&
+                r.SboId == SboIdEnums.neware_201304 &&
+                r.Remark.Contains("【可清单】"))
+                .ToListAsync();
+
+            var batchSaleOrderRemarkCannotClear = await unitWork.Find<SaleOrdrRemark>(r =>
+                orderIds.Contains(r.DocEntry) &&
+                r.SboId == SboIdEnums.neware_201304 &&
+                r.Remark.Contains("不可清单"))
+                .ToListAsync();
+
+            // 判断是否应该截止计算：只有当【可清单】比不可清单晚时才截止
+            var remarkDic = new Dictionary<int, SaleOrdrRemark>();
+            var canClearDict = batchSaleOrderRemarkCanClear.GroupBy(x => x.DocEntry).ToDictionary(g => g.Key, g => g.OrderByDescending(x => x.CreateDate).First());
+            var cannotClearDict = batchSaleOrderRemarkCannotClear.GroupBy(x => x.DocEntry).ToDictionary(g => g.Key, g => g.OrderByDescending(x => x.CreateDate).First());
+
+            foreach (var orderId in orderIds)
+            {
+                var hasCanClear = canClearDict.TryGetValue(orderId, out var canClearRemark);
+                var hasCannotClear = cannotClearDict.TryGetValue(orderId, out var cannotClearRemark);
+                if ( (hasCanClear && !hasCannotClear) || (hasCanClear && hasCannotClear && canClearRemark.CreateDate > cannotClearRemark.CreateDate))
+                {
+                    // 只有【可清单】，使用它
+                    remarkDic[orderId] = canClearRemark;
+                }
+            }
+
+            // =====================================================================
+
+            // 遍历订单，使用预加载的数据进行处理
+            foreach (var order in orders)
+            {
+                await ProcessSingleOrderByRangeInternal(
+                    unitWork,
+                    historicalOverdueCalculationService,
+                    order,
+                    endDate,
+                    customerTypes,
+                    penaltyRules,
+                    batchSaleOrders,
+                    batchPayTerms,
+                    batchDeliveries,
+                    batchReceipts,
+                    batchReturns,
+                    batchRefunds,
+                    batchClearRecons,
+                    batchSaleOrderPlugins,
+                    batchSlps,
+                    remarkDic
+                );
+            }
+        }
