+        public static async Task<Dictionary<int, List<SaleRefund>>> GetBatchRefundHistoryInternal(IUnitWork unitWork, List<int> orderIds)
+        {
+            var result = new Dictionary<int, List<SaleRefund>>();
+            if (orderIds == null || orderIds.Count == 0)
+            {
+                return result;
+            }
+
+            var refunds = await unitWork.Find<SaleRefund>(x =>
+                    x.OrderId.HasValue &&
+                    orderIds.Contains(x.OrderId.Value) &&
+                    x.DocDate.HasValue &&
+                    x.Status == SaleRefundStatus.Pass)
+                .ToListAsync();
+
+            foreach (var group in refunds.GroupBy(x => x.OrderId.Value))
+            {
+                result[group.Key] = group.OrderBy(x => x.DocDate).ToList();
+            }
+
+            return result;
