+        /// <summary>
+        /// 根据订单DocEntry列表获取对应的sale_ordr_plugin列表
+        /// </summary>
+        /// <param name="docEntries">订单DocEntry列表</param>
+        /// <returns>sale_ordr_plugin列表，对于未匹配的DocEntry会创建带默认值的新对象</returns>
+        public async Task<List<SaleOrderPlugin>> GetSaleOrderPluginsByDocEntries(List<int> docEntries)
+        {
+            if (docEntries == null || !docEntries.Any())
+            {
+                return new List<SaleOrderPlugin>();
+            }
+
+            // 去重
+            var uniqueDocEntries = docEntries.Distinct().ToList();
+
+            // 查询已存在的sale_ordr_plugin
+            var existingPlugins = await UnitWork.Find<SaleOrderPlugin>(
+                p => uniqueDocEntries.Contains(p.DocEntry) &&
+                     p.SboId == SboIdEnums.neware_201304)
+                .ToListAsync();
+
+            var existingDocEntries = existingPlugins.Select(p => p.DocEntry).ToHashSet();
+
+            // 为未匹配的DocEntry创建新的默认对象
+            foreach (var docEntry in uniqueDocEntries.Where(de => !existingDocEntries.Contains(de)))
+            {
+                existingPlugins.Add(new SaleOrderPlugin
+                {
+                    DocEntry = docEntry,
+                    SboId = SboIdEnums.neware_201304,
+                    CanInterRecon = InterReconEnums.Forbid,
+                    NeedReturn = NeedReturnEnums.None,
+                    CheckedNeedReturn = false,
+                    NeedBill = NeedBillEnums.NotBill
+                    // 其他字段保持默认值（null 或 0）
+                });
+            }
+
+            return existingPlugins;
+        }
