+        public async Task<(int orderCount, int pluginCount)> RecalculateHistoricalOverdueForCompletedOrdersAsync()
+        {
+            // 1. 获取已完成订单
+            var orders = await GetCompletedOrdersWithHistoricalOverdue();
+            if (orders == null || !orders.Any())
+            {
+                return (0, 0);
+            }
+
+            var orderDocEntries = orders.Select(o => o.DocEntry).ToList();
+
+            // 2. 获取对应的sale_ordr_plugin列表（未匹配到的会创建默认值对象）
+            var plugins = await GetSaleOrderPluginsByDocEntries(orderDocEntries);
+
+            // 4. 调用重新计算方法
+            await RecalculateHistoricalOverdueAsync(plugins);
+
+            return (orders.Count, plugins.Count);
