+        /// <summary>
+        /// 并行重新计算历史逾期（动态自适应并行度）
+        /// </summary>
+        /// <param name="initialDegree">初始并行度</param>
+        /// <param name="maxDegree">最大并行度</param>
+        /// <param name="slowTaskThresholdSeconds">慢任务阈值（秒）</param>
+        /// <returns>处理结果</returns>
+        public async Task<(int orderCount, int pluginCount, int successCount, int failedCount)> 
+            RecalculateHistoricalOverdueForCompletedOrdersParallelAsync(
+                int initialDegree = 4, 
+                int maxDegree = 10, 
+                int slowTaskThresholdSeconds = 30)
+        {
+            var stopwatch = System.Diagnostics.Stopwatch.StartNew();
+            LogHelper.Info($"[并行重算] 开始处理，初始并行度：{initialDegree}，最大并行度：{maxDegree}，慢任务阈值：{slowTaskThresholdSeconds}秒", 
+                nameof(HistoricalOverdueImportService), nameof(RecalculateHistoricalOverdueForCompletedOrdersParallelAsync));
+
+            var orders = await GetCompletedOrdersWithHistoricalOverdue();
+            if (orders == null || !orders.Any())
+            {
+                LogHelper.Info($"[并行重算] 没有订单需要处理", 
+                    nameof(HistoricalOverdueImportService), nameof(RecalculateHistoricalOverdueForCompletedOrdersParallelAsync));
+                return (0, 0, 0, 0);
+            }
+
+            var orderDocEntries = orders.Select(o => o.DocEntry).ToList();
+            var plugins = await GetSaleOrderPluginsByDocEntries(orderDocEntries);
+            var orderIds = plugins.Select(p => p.DocEntry).Distinct().ToList();
+
+            LogHelper.Info($"[并行重算] 共{orders.Count}个订单，预加载批量数据中...", 
+                nameof(HistoricalOverdueImportService), nameof(RecalculateHistoricalOverdueForCompletedOrdersParallelAsync));
+
+            var preloadStopwatch = System.Diagnostics.Stopwatch.StartNew();
+            var preloadedData = await PreloadBatchDataForParallelAsync(orderIds, plugins);
+            preloadStopwatch.Stop();
+            LogHelper.Info($"[并行重算] 批量数据预加载完成，耗时：{preloadStopwatch.Elapsed.TotalSeconds:F2}秒", 
+                nameof(HistoricalOverdueImportService), nameof(RecalculateHistoricalOverdueForCompletedOrdersParallelAsync));
+
+            int successCount = 0;
+            int failedCount = 0;
+            int currentDegree = initialDegree;
+            var lockObj = new object();
+            var taskStartTimes = new Dictionary<int, DateTime>();
+            var semaphore = new System.Threading.SemaphoreSlim(initialDegree, maxDegree);
+
+            var tasks = orders.Select(async (order, index) =>
+            {
+                await semaphore.WaitAsync();
+                var taskStartTime = DateTime.Now;
+                int taskDegree = currentDegree;
+                
+                lock (lockObj)
+                {
+                    taskStartTimes[index] = taskStartTime;
+                }
+
+                try
+                {
+                    using (var scope = _serviceProvider.CreateScope())
+                    {
+                        var scopedUnitWork = scope.ServiceProvider.GetRequiredService<IUnitWork>();
+                        var scopedHistoricalCalcService = scope.ServiceProvider.GetRequiredService<HistoricalOverdueCalculationService>();
+                        await ProcessSingleOrderInParallelAsync(
+                            scopedUnitWork,
+                            scopedHistoricalCalcService,
+                            order,
+                            preloadedData);
+
+                        lock (lockObj)
+                        {
+                            successCount++;
+                            var elapsed = stopwatch.Elapsed.TotalSeconds;
+                            Console.WriteLine($"[进度] {successCount + failedCount}/{orders.Count} - 成功: {successCount}, 失败: {failedCount}, 耗时: {elapsed:F1}秒, 当前并行度: {taskDegree},开始时间{taskStartTime},结束时间{DateTime.Now}, 处理订单{order.DocEntry} 成功");
+                        }
+                    }
+                }
+                catch (Exception ex)
+                {
+                    lock (lockObj)
+                    {
+                        failedCount++;
+                        Console.WriteLine($"[进度] {successCount + failedCount}/{orders.Count} - 成功: {successCount}, 失败: {failedCount} - 订单{order.DocEntry}错误: {ex.Message}");
+                    }
+                    LogHelper.Error(ex, $"[并行重算] 处理订单{order.DocEntry}失败", 
+                        nameof(HistoricalOverdueImportService), nameof(RecalculateHistoricalOverdueForCompletedOrdersParallelAsync));
+                }
+                finally
+                {
+                    semaphore.Release();
+                    lock (lockObj)
+                    {
+                        taskStartTimes.Remove(index);
+                    }
+                }
+            }).ToList();
+
+            var monitorTask = Task.Run(async () =>
+            {
+                while (!Task.WhenAll(tasks).IsCompleted)
+                {
+                    await Task.Delay(5000);
+                    lock (lockObj)
+                    {
+                        var now = DateTime.Now;
+                        var slowTasks = taskStartTimes.Where(kv => (now - kv.Value).TotalSeconds > slowTaskThresholdSeconds).ToList();
+                        
+                        if (slowTasks.Any() && currentDegree < maxDegree)
+                        {
+                            int oldDegree = currentDegree;
+                            int increase = Math.Min(2, maxDegree - currentDegree);
+                            currentDegree += increase;
+                            
+                            for (int i = 0; i < increase; i++)
+                            {
+                                semaphore.Release();
+                            }
+                            
+                            Console.WriteLine($"[自适应] 检测到{slowTasks.Count}个慢任务，并行度从{oldDegree}增加到{currentDegree}");
+                            LogHelper.Info($"[并行重算] 检测到{slowTasks.Count}个慢任务（超过{slowTaskThresholdSeconds}秒），并行度从{oldDegree}增加到{currentDegree}", 
+                                nameof(HistoricalOverdueImportService), nameof(RecalculateHistoricalOverdueForCompletedOrdersParallelAsync));
+                        }
+                    }
+                }
+            });
+
+            await Task.WhenAll(tasks);
+            await monitorTask;
+
+            stopwatch.Stop();
+            var throughput = (successCount + failedCount) / stopwatch.Elapsed.TotalSeconds;
+            
+            Console.WriteLine($"[完成] 总耗时: {stopwatch.Elapsed.TotalSeconds:F1}秒, 成功: {successCount}, 失败: {failedCount}, 吞吐量: {throughput:F2}订单/秒");
+            LogHelper.Info($"[并行重算] 处理完成，总耗时：{stopwatch.Elapsed.TotalSeconds:F2}秒，成功：{successCount}，失败：{failedCount}，吞吐量：{throughput:F2}订单/秒", 
+                nameof(HistoricalOverdueImportService), nameof(RecalculateHistoricalOverdueForCompletedOrdersParallelAsync));
+
+            return (orders.Count, plugins.Count, successCount, failedCount);
+        }
