+        /// <summary>
+        /// 预加载批量数据（用于并行处理）
+        /// </summary>
+        private async Task<ParallelPreloadedData> PreloadBatchDataForParallelAsync(List<int> orderIds, List<SaleOrderPlugin> plugins)
+        {
+            var data = new ParallelPreloadedData();
+
+            var customerTypes = await _customerCommonApp.GetMainlandCustomerType();
+            var penaltyRuleSchool = await GetApplicablePenaltyRule(true);
+            var penaltyRuleOther = await GetApplicablePenaltyRule(false);
+            data.PenaltyRules = new Dictionary<bool, PenaltyRuleDefinition>
+            {
+                { true, penaltyRuleSchool },
+                { false, penaltyRuleOther }
+            };
+            data.CustomerTypes = customerTypes;
+
+            data.BatchSaleOrders = await _historicalOverdueCalculationService.GetBatchSaleOrdersAsync(orderIds);
+
+            var groupNums = data.BatchSaleOrders.Values
+                .Where(o => o != null && o.GroupNum.HasValue)
+                .Select(o => o.GroupNum.Value)
+                .Distinct()
+                .ToList();
+            data.BatchPayTerms = await _historicalOverdueCalculationService.GetBatchPayTermsAsync(groupNums);
+
+            data.BatchDeliveries = await _historicalOverdueCalculationService.GetBatchAlreadyDeliverysAsync(orderIds);
+            data.BatchReceipts = await GetBatchReceiptHistoryAsync(orderIds);
+
+            var endDate = DateTime.Now.Date;
+            data.BatchReturns = await _historicalOverdueCalculationService.GetBatchHistoricalReturnsAsync(orderIds, endDate);
+            data.BatchRefunds = await GetBatchRefundHistoryAsync(orderIds);
+            data.BatchClearRecons = await GetBatchHistoricalClearReconsInternal(UnitWork, orderIds);
+
+            data.BatchSaleOrderPlugins = plugins.ToDictionary(p => p.DocEntry, p => p);
+
+            //10. 提取所有相关订单的插件的关联备注（【可清单】和不可清单）
+            var batchSaleOrderRemarkCanClear = await UnitWork.Find<SaleOrdrRemark>(r =>
+                orderIds.Contains(r.DocEntry) &&
+                r.SboId == SboIdEnums.neware_201304 &&
+                r.Remark.Contains("【可清单】"))
+                .ToListAsync();
+            var batchSaleOrderRemarkCannotClear = await UnitWork.Find<SaleOrdrRemark>(r =>
+                orderIds.Contains(r.DocEntry) &&
+                r.SboId == SboIdEnums.neware_201304 &&
+                r.Remark.Contains("不可清单"))
+                .ToListAsync();
+
+            // 判断是否应该截止计算：只有当【可清单】比不可清单晚时才截止
+            var remarkDic = new Dictionary<int, SaleOrdrRemark>();
+            var canClearDict = batchSaleOrderRemarkCanClear.GroupBy(x => x.DocEntry).ToDictionary(g => g.Key, g => g.OrderByDescending(x => x.CreateDate).First());
+            var cannotClearDict = batchSaleOrderRemarkCannotClear.GroupBy(x => x.DocEntry).ToDictionary(g => g.Key, g => g.OrderByDescending(x => x.CreateDate).First());
+
+            foreach (var orderId in orderIds)
+            {
+                var hasCanClear = canClearDict.TryGetValue(orderId, out var canClearRemark);
+                var hasCannotClear = cannotClearDict.TryGetValue(orderId, out var cannotClearRemark);
+
+                if ( (hasCanClear && !hasCannotClear) || (hasCanClear && hasCannotClear && canClearRemark.CreateDate > cannotClearRemark.CreateDate) )
+                {
+                    // 只有【可清单】，使用它
+                    remarkDic[orderId] = canClearRemark;
+                }
+                // 如果只有不可清单或都没有，不添加到remarkDic
+            }
+
+            var orders = await UnitWork.Find<ORDR>(o => orderIds.Contains(o.DocEntry)).ToListAsync();
+            var slpCodes = orders.Where(o => o.SlpCode.HasValue)
+                .Select(o => o.SlpCode.Value)
+                .Distinct()
+                .ToList();
+            data.BatchSlps = await GetBatchSlpsAsync(slpCodes);
+
+            return data;
+        }
