+                .ToListAsync();
+
+            var eventIds = events.Select(x => x.Id).ToList();
+            var ledgers = await unitWork.Find<PenaltyLedger>(e => eventIds.Contains(e.EventId)).ToListAsync();
+
+            if (events.Any())
+            {
+                await unitWork.BatchDeleteAsync<PenaltyLedger>(ledgers.ToArray());
+                await unitWork.SaveAsync();
+                await unitWork.BatchDeleteAsync<PenaltyEvent>(events.ToArray());
+                await unitWork.SaveAsync();
+            }
+
+            await ProcessSingleOrderInternal(
+                unitWork,
+                historicalOverdueCalculationService,
+                order,
+                DateTime.Now.Date,
+                null,
+                preloadedData.CustomerTypes,
+                preloadedData.PenaltyRules,
+                preloadedData.BatchSaleOrders,
+                preloadedData.BatchPayTerms,
+                preloadedData.BatchDeliveries,
+                preloadedData.BatchReceipts,
+                preloadedData.BatchReturns,
+                preloadedData.BatchRefunds,
+                preloadedData.BatchClearRecons,
+                preloadedData.BatchSaleOrderPlugins,
+                preloadedData.BatchSlps,
+                preloadedData.RemarkDic);
