+        /// <summary>
+        /// 查询所有已收款完成的订单
+        /// </summary>
+        public async Task<List<ORDR>> GetCompletedOrdersWithHistoricalOverdue()
+        {
+            // 查询所有未取消的订单，后续在处理过程中检查收款历史
+            var allOrders = await UnitWork.Find<ORDR>(o => o.CANCELED != "Y").ToListAsync();
