+        /// <returns>订单ID与退货记录列表的映射</returns>
+        private static async Task<Dictionary<int, List<HistoricalOverdueCalculationService.ReturnForOverDue>>> GetBatchHistoricalReturnsInternal(IUnitWork unitWork, List<int> orderIds, DateTime calculationDate)
+        {
+            var result = new Dictionary<int, List<HistoricalOverdueCalculationService.ReturnForOverDue>>();
+
+            var directReturns = await unitWork.Find<ORIN>(x => 
+                orderIds.Select(id => id.ToString()).Contains(x.U_DevEntry) && 
+                x.CANCELED != "Y" && 
+                x.DocDate <= calculationDate)
+                .Select(x => new { 
+                    OrderId = int.Parse(x.U_DevEntry),
+                    Return = new HistoricalOverdueCalculationService.ReturnForOverDue
+                    {
+                        DocEntry = x.DocEntry,
+                        DocDate = x.DocDate,
+                        DocTotal = x.DocTotal,
+                        DocTotalFc = x.DocTotalFC
+                    }
+                })
+                .ToListAsync();
+
+            var indirectReturns = await unitWork.Find<DLN1>(x => x.BaseEntry.HasValue && orderIds.Contains(x.BaseEntry.Value))
+             .Join(unitWork.Find<INV1>(null),
+                   x => new { BaseEntry = x.DocEntry, BaseType = new int?(15) },
+                   y => new { y.BaseEntry, y.BaseType },
+                   (x, y) => new { x, y })
+             .Join(unitWork.Find<RIN1>(null),
+                   x => new { BaseEntry = x.y.BaseEntry, BaseType = new int?(13) },
+                   y => new { y.BaseEntry, y.BaseType },
+                   (x, y) => new { DLN1 = x.x, INV1 = x.y, RIN1 = y })
+             .Join(unitWork.Find<ORIN>(null),
+                   x => x.RIN1.DocEntry,
+                   y => y.DocEntry,
+                   (x, y) => new { x.DLN1, x.INV1, x.RIN1, ORIN = y })
+             .Where(x => x.ORIN.CANCELED != "Y" && x.ORIN.DocDate <= calculationDate && (x.ORIN.U_DevEntry == null || x.ORIN.U_DevEntry == ""))
+             .Select(x => new { x.DLN1, x.ORIN.DocEntry, x.RIN1.LineTotal, x.ORIN.DocDate, x.ORIN.DocCur, x.RIN1.Quantity, x.RIN1.Price })
+             .ToListAsync();
+
+            var processedIndirectReturns = indirectReturns.GroupBy(x => new { x.DLN1.BaseEntry, x.DocEntry, x.DocDate, x.DocCur })
+                .Select(g => new {
+                    OrderId = g.Key.BaseEntry,
+                    Return = new HistoricalOverdueCalculationService.ReturnForOverDue
+                    {
+                        DocEntry = g.Key.DocEntry,
+                        DocDate = g.Key.DocDate,
+                        DocTotal = g.Sum(s => s.LineTotal),
+                        DocTotalFc = g.Key.DocCur != "RMB" ? g.Sum(s => s.Price * s.Quantity) : 0M
+                    }
+                })
+                .ToList();
+
+            var allReturns = new List<(int OrderId, HistoricalOverdueCalculationService.ReturnForOverDue Return)>();
