+        /// <param name="unitWork">工作单元</param>
+        /// <param name="orderIds">订单ID列表</param>
+        /// <returns>订单ID与清账记录列表的映射</returns>
+        public static async Task<Dictionary<int, List<HistoricalOverdueCalculationService.ClearReconForOverDue>>> GetBatchHistoricalClearReconsInternal(IUnitWork unitWork, List<int> orderIds)
+        {
+            var result = new Dictionary<int, List<HistoricalOverdueCalculationService.ClearReconForOverDue>>();
+
+            // 查询所有审批通过的清账记录
+            var clearRecons = await unitWork.Find<FinanceClearReconJournal>(
+                x => x.BaseDocEntry.HasValue &&
+                     orderIds.Contains(x.BaseDocEntry.Value) &&
+                     x.Status == ClearReconcStatus.审批通过)
+                .Select(x => new {
+                    OrderId = x.BaseDocEntry.Value,
+                    ClearRecon = new HistoricalOverdueCalculationService.ClearReconForOverDue
+                    {
+                        BaseDocEntry = x.BaseDocEntry,
+                        CreateDate = x.CreateDate,
+                        ClearReconAmt = x.ClearReconAmt,
+                        ClearReconAmtFc = x.ClearReconAmtFc
+                    }
+                })
+                .ToListAsync();
+
+            // 按订单ID分组
+            foreach (var group in clearRecons.GroupBy(r => r.OrderId))
+            {
+                result[group.Key] = group.Select(r => r.ClearRecon)
+                                         .OrderBy(r => r.CreateDate)
+                                         .ToList();
+            }
+
+            return result;
+        }
