+        /// <summary>
+        /// 处理单个订单
+        /// </summary>
+        private async Task ProcessSingleOrder(
+            ORDR order,
+            DateTime calculationDate,
+            DateTime? generationStartDate = null,
+            List<MainlandCustomerTypeDto> customerTypes = null,
+            Dictionary<bool, PenaltyRuleDefinition> penaltyRules = null,
+            Dictionary<int, HistoricalOverdueCalculationService.SaleOrderForOverDue> batchSaleOrders = null,
+            Dictionary<int, PayTermSave> batchPayTerms = null,
+            Dictionary<int, List<HistoricalOverdueCalculationService.DeliveryForOverDue>> batchDeliveries = null,
+            Dictionary<int, List<ReceiptForOrder>> batchReceipts = null,
+            Dictionary<int, List<HistoricalOverdueCalculationService.ReturnForOverDue>> batchReturns = null,
+            Dictionary<int, List<SaleRefund>> batchRefunds = null,
+            Dictionary<int, List<HistoricalOverdueCalculationService.ClearReconForOverDue>> batchClearRecons = null,
+            Dictionary<int, SaleOrderPlugin> batchSaleOrderPlugins = null,
+            Dictionary<int, OSLP> batchSlps = null,
+            Dictionary<int, SaleOrdrRemark> remarkDic = null
+        )
+        {
+            try
+            {
+                // ================== 使用批量预加载数据 ==================
+                
+                // 1. 获取订单详情
+                if (!batchSaleOrders.TryGetValue(order.DocEntry, out var saleOrderForCalc))
+                {
+                    // 如果批量数据中没有，回退到单条查询
+                    saleOrderForCalc = await _historicalOverdueCalculationService.GetSaleOrderAsync(order.DocEntry);
+                    if (saleOrderForCalc == null) return;
+                }
+                
+                // 2. 获取付款条款
+                PayTermSave payTerm = null;
+                if (saleOrderForCalc.GroupNum.HasValue)
+                {
+                    batchPayTerms?.TryGetValue(saleOrderForCalc.GroupNum.Value, out payTerm);
+                }
+
+                // 3. 获取发货记录
+                if (!batchDeliveries.TryGetValue(order.DocEntry, out List<HistoricalOverdueCalculationService.DeliveryForOverDue> deliveryForCalcList))
+                {
+                    deliveryForCalcList = new List<HistoricalOverdueCalculationService.DeliveryForOverDue>();
+                }
+
+                // 4. 获取收款记录
+                if (!batchReceipts.TryGetValue(order.DocEntry, out List<ReceiptForOrder> allReceipts))
+                {
+                    allReceipts = new List<ReceiptForOrder>();
+                }
+
+                // 5. 获取退货记录
+                if (!batchReturns.TryGetValue(order.DocEntry, out List<HistoricalOverdueCalculationService.ReturnForOverDue> allReturns))
+                {
+                    allReturns = new List<HistoricalOverdueCalculationService.ReturnForOverDue>();
+                }
+
+                if (batchRefunds == null || !batchRefunds.TryGetValue(order.DocEntry, out List<SaleRefund> allRefunds))
+                {
+                    allRefunds = new List<SaleRefund>();
+                }
+
+                // 6. 获取清账记录
+                if (!batchClearRecons.TryGetValue(order.DocEntry, out List<HistoricalOverdueCalculationService.ClearReconForOverDue> allClearRecons))
+                {
+                    allClearRecons = new List<HistoricalOverdueCalculationService.ClearReconForOverDue>();
+                }
+
+                // 借用单，重新设置计算逾期的发货日期
+                SetBorrowTypeDeliveryDocDate(deliveryForCalcList, saleOrderForCalc);
+
+                // ====================================================================
+                // 创建事件列表，合并收款和交货事件
+                var events = new List<OrderEvent>();
+                
+                // 添加收款事件 (使用预加载的 receipts)
+                foreach (var receipt in allReceipts)
+                {
+                    events.Add(new OrderEvent
+                    {
+                        EventDate = receipt.DocDate.Value,
+                        EventType = OrderEventType.Payment,
+                        ReferenceId = receipt.DocEntry.ToString(),
+                        Amount = receipt.AppliedAmount
+                    });
+                }
+
+                // 添加交货事件 (使用预加载的 deliveries)
+                foreach (var delivery in deliveryForCalcList)
+                {
+                    events.Add(new OrderEvent
+                    {
+                        EventDate = delivery.DocDate.Value,
+                        EventType = OrderEventType.Delivery,
+                        ReferenceId = delivery.DocEntry.ToString(),
+                        Amount = delivery.DocTotal.Value
+                    });
+                }
+                
+                // 添加退货事件 (使用预加载的 returns)
+                foreach (var returnOrder in allReturns)
+                {
+                    events.Add(new OrderEvent
+                    {
+                        EventDate = returnOrder.DocDate.Value,
+                        EventType = OrderEventType.Return,
+                        ReferenceId = returnOrder.DocEntry.ToString(),
+                        Amount = returnOrder.DocTotal.Value
+                    });
+                }
+
+                foreach (var refund in allRefunds)
+                {
+                    events.Add(new OrderEvent
+                    {
+                        EventDate = refund.DocDate.Value.Date,
+                        EventType = OrderEventType.Refund,
+                        ReferenceId = refund.Id.ToString(),
+                        Amount = refund.ApplyAmount
+                    });
+                }
