+                        EventDate = remark.CreateDate,
+                        EventType = OrderEventType.CanClearRecon,
+                        ReferenceId = "CanClearRecon",
+                        Amount = 0
+                    });
+                }
+
+                // 添加计算日期作为最后一个事件
+                events.Add(new OrderEvent
+                {
+                    EventDate = calculationDate,
+                    EventType = OrderEventType.CalculationEnd,
+                    ReferenceId = "CalculationEnd",
+                    Amount = 0
+                });
+                
+                // 按事件日期排序
+                events = events.OrderBy(e => e.EventDate).ToList();
+                
+                // 合并同一天的同一类型事件（不包括 CanClearRecon 和 CalculationEnd）
+                events = events
+                    .GroupBy(e => new { e.EventDate.Date, e.EventType })
+                    .Select(g => new OrderEvent
+                    {
+                        EventDate = g.Key.Date,
+                        EventType = g.Key.EventType,
+                        ReferenceId = string.Join(",", g.Select(e => e.ReferenceId)),
+                        Amount = g.Sum(e => e.Amount)
+                    })
+                    .OrderBy(e => e.EventDate)
+                    .ToList();
+                
+                //然后去掉 events CanClearRecon后面的事件 ，CanClearRecon事件的金额为上一个事件的金额
+                if (events.Any(e => e.EventType == OrderEventType.CanClearRecon))
+                {
+                    var canClearReconIndex = events.FindIndex(e => e.EventType == OrderEventType.CanClearRecon);
+                    var canClearReconDate = events[canClearReconIndex].EventDate;
+                    
+                    // 若有和可清单事件同一天的事件，去掉其他同一天的事件，只保留可清单事件
+                    events = events.Where(e => e.EventType == OrderEventType.CanClearRecon || e.EventDate != canClearReconDate).ToList();
+
+                    // 重新排序事件
+                    events = events.OrderBy(e => e.EventDate).ToList();
+                    
+                    // 重新获取 CanClearRecon 事件的索引
+                    canClearReconIndex = events.FindIndex(e => e.EventType == OrderEventType.CanClearRecon);
+
+                    // 如果前面还有别的事件，使用前一个事件的金额作为清账事件的金额
+                    if (canClearReconIndex > 0)
+                    {
+                        events[canClearReconIndex].Amount = events[canClearReconIndex - 1].Amount;
+                    }
+                    events = events.Take(canClearReconIndex + 1).ToList();
+                }
+
+
+                if (events.Count == 0)
+                    return;
+                
+                // 获取订单的创建日期作为起始日期
+                DateTime currentPeriodStart = order.DocDate.Value;
+                PenaltyEvent currentEvent = null;
+                decimal previousOverdueAmount = 0;
+                
+                // 6. 使用预加载的客户类型
+                customerTypes ??= await _customerCommonApp.GetMainlandCustomerType();
+
+                // 7. 使用预加载的销售订单插件
+                batchSaleOrderPlugins.TryGetValue(order.DocEntry, out SaleOrderPlugin saleOrderPlugin);
+
+                var customerType = customerTypes.FirstOrDefault(ct => ct.CardCode == order.CardCode);
+                var isSchoolOrResearch = customerType != null && (customerType.CardType.Contains("校") || customerType.CardType.Contains("研"));
+
+                // 8. 使用预加载的罚息规则
+                if (!penaltyRules.TryGetValue(isSchoolOrResearch, out PenaltyRuleDefinition rule))
+                {
+                    // 如果批量数据中没有，回退到单条查询
+                    rule = await GetApplicablePenaltyRule(isSchoolOrResearch);
+                }
+
+                if (rule == null)
+                    return;
+                
+                // 解析阶梯利率
+                var rateTiers = Newtonsoft.Json.JsonConvert.DeserializeObject<List<InterestRateTier>>(rule.Param_String1);
+                
+                // 9. 使用预加载的销售员信息
+                OSLP slp = null;
+                if (order.SlpCode.HasValue && !batchSlps.TryGetValue(order.SlpCode.Value, out slp))
+                {
+                    // 如果批量数据中没有，回退到单条查询
+                    slp = await UnitWork.Find<OSLP>(s => s.SlpCode == order.SlpCode.Value).FirstOrDefaultAsync();   
+                }
+                
+                // 处理每个事件期间
+                foreach (var @event in events)
+                {
+                    // 计算当前期间的结束日期
+                    DateTime periodEnd = @event.EventDate;
+
+                    bool isInterRecon = false;
+                    if(@event.EventType== OrderEventType.CanClearRecon)
+                    {
+                        isInterRecon = true;
+                    }
+
+                    // 处理当前期间的逾期情况，带事件跟踪
+                    // 传入预加载的数据
+                    var eventTrackingResult = await ProcessOverduePeriodWithEventTracking(
+                        order,
+                        currentPeriodStart,
+                        periodEnd,
+                        currentEvent,
+                        previousOverdueAmount,
+                        generationStartDate,
+                        // 注入预加载数据
+                        saleOrderForCalc,
+                        payTerm,
+                        deliveryForCalcList,
+                        allReturns,
+                        allReceipts,
+                        allRefunds,
+                        allClearRecons,
+                        saleOrderPlugin,
+                        rule,
+                        rateTiers,
+                        slp,
+                        isInterRecon
+                    );
+                    if (@event.EventType == OrderEventType.CanClearRecon)
+                    {
+                        break;
+                    }
+                    currentEvent = eventTrackingResult.CurrentEvent;
+                    previousOverdueAmount = eventTrackingResult.PreviousOverdueAmount;
+                    
+                    // 更新下一个期间的起始日期为本次事件日期的第二天
+                    currentPeriodStart = periodEnd.AddDays(1);
+                }
+            }
+            catch (Exception ex)
+            {
+                LogHelper.Error(ex, $"处理订单{order.DocEntry}失败", nameof(HistoricalOverdueImportService), nameof(ProcessSingleOrder));
+            }
+        }
