+        /// <summary>
+        /// 计算罚息金额
+        /// </summary>
+        private static (decimal,decimal) CalculatePenaltyAmount( HistoricalOverdueCalculationService.OverDueAmountAndDays overdueInfo,  SaleOrderPlugin saleOrderPlugin,List<InterestRateTier> rateTiers)
+        {
+            bool isNoReceipt = saleOrderPlugin?.NeedReturn == NeedReturnEnums.Select;
+            decimal factor = isNoReceipt ? 0.5M : 1.0M;
+            if (rateTiers == null || !rateTiers.Any())
+                return (0,0);
+
+            // 匹配当前逾期天数对应的利率
+
+            var matchedTier = rateTiers.FirstOrDefault(tier => 
+                (tier.Min == null || overdueInfo.U_OverDue_Days >= tier.Min) && 
+                (tier.Max == null || overdueInfo.U_OverDue_Days <= tier.Max));
+            if (matchedTier == null)
+                return (0,0);
+
+            // 计算每日利率
+            decimal dailyRate = matchedTier.Rate.Value / 100m / 365m;
+
+            // 计算罚息金额
+            return (overdueInfo.U_Due_Amt * dailyRate * factor,dailyRate);
+        }
+
+        /// <summary>
+        /// 计算罚息金额（内部版本，用于并行处理）
+        /// </summary>
+        private static (decimal,decimal) CalculatePenaltyAmountInternal(HistoricalOverdueCalculationService.OverDueAmountAndDays overdueInfo, SaleOrderPlugin saleOrderPlugin,List<InterestRateTier> rateTiers)
+        {
+            bool isNoReceipt = saleOrderPlugin?.NeedReturn == NeedReturnEnums.Select;
+            decimal factor = isNoReceipt ? 0.5M : 1.0M;
+            if (rateTiers == null || !rateTiers.Any())
+                return (0,0);
+
+            // 匹配当前逾期天数对应的利率
+            var matchedTier = rateTiers.FirstOrDefault(tier => (tier.Min == null || overdueInfo.U_OverDue_Days > tier.Min) && (tier.Max == null || overdueInfo.U_OverDue_Days <= tier.Max));
+            if (matchedTier == null)
+                return (0,0);
+
+            decimal dailyRate = matchedTier.Rate.Value / 100m / 365m;
+            return (overdueInfo.U_Due_Amt * dailyRate * factor,dailyRate);
+        }
