+        /// <summary>
+        /// 借用单重新设置计算逾期的发货日期
+        /// </summary>
+        /// <param name="deliveryInfos">发货信息列表</param>
+        /// <param name="saleOrderForOverDue">销售订单信息</param>
+        public static void SetBorrowTypeDeliveryDocDate(List<HistoricalOverdueCalculationService.DeliveryForOverDue> deliveryInfos, HistoricalOverdueCalculationService.SaleOrderForOverDue saleOrderForOverDue)
+        {
+            if (saleOrderForOverDue.IsBorrowed && deliveryInfos.Count > 0)
+            {
+                var maxDeliveryDate = deliveryInfos.Where(x => x.DocDate.HasValue).Max(x => x.DocDate.Value);
+                //退回日期 > 交货日期（最新）：从退回日期第二天开始计算逾期
+                if (saleOrderForOverDue.BorrowReturnDate.HasValue && saleOrderForOverDue.BorrowReturnDate > maxDeliveryDate)
+                {
+                    deliveryInfos.ForEach(deliveryInfo => deliveryInfo.DocDate = saleOrderForOverDue.BorrowReturnDate);
+                    saleOrderForOverDue.BorrowReturnDateIsNewest = true;
+                }
+                //退回日期 < 交货日期（最新）：交货日期（最新） +借用天数后 第二天开始计算逾期
+                else if(saleOrderForOverDue.BorrowReturnDate.HasValue && saleOrderForOverDue.BorrowReturnDate < maxDeliveryDate)
+                {
+                    deliveryInfos.ForEach(deliveryInfo => deliveryInfo.DocDate = maxDeliveryDate.AddDays(saleOrderForOverDue.BorrowDays));
+                }
+                //没有退回日期，交货日期（最新） + 借用天数后 第二天开始计算逾期
+                else if (!saleOrderForOverDue.BorrowReturnDate.HasValue)
+                {
+                    deliveryInfos.ForEach(deliveryInfo => deliveryInfo.DocDate = maxDeliveryDate.AddDays(saleOrderForOverDue.BorrowDays));
+                }
+            }
+        }
