+        /// <summary>
+        /// 将 Event 结束操作加入待更新队列（延迟批量执行）
+        /// </summary>
+        private static void QueueEventUpdate(List<(int EventId, DateTime ResolvedDate, string Description)> pendingUpdates, PenaltyEvent currentEvent, DateTime endDate)
+        {
