+        /// <summary>
+        /// 批量更新 PenaltyEvent（使用单条 SQL 的 CASE WHEN 语句）
+        /// </summary>
+        private static async Task BatchUpdatePenaltyEventsAsync(IUnitWork unitWork, List<(int EventId, DateTime ResolvedDate, string Description)> pendingUpdates)
+        {
+            if (pendingUpdates == null || pendingUpdates.Count == 0)
+                return;
+
+            var eventIds = string.Join(",", pendingUpdates.Select(u => u.EventId));
+
+            // 构建 CASE WHEN 语句
+            var resolvedDateCases = string.Join("\n                ",
+                pendingUpdates.Select(u => $"WHEN Id = {u.EventId} THEN '{u.ResolvedDate:yyyy-MM-dd HH:mm:ss}'"));
+
+            var descriptionCases = string.Join("\n                ",
+                pendingUpdates.Select(u => $"WHEN Id = {u.EventId} THEN '{u.Description.Replace("'", "''")}'"));
+
+            var sql = $@"
+                UPDATE penalty_events
+                SET
+                    ResolvedDate = CASE
+                        {resolvedDateCases}
+                    END,
+                    EventStatus = 'RESOLVED',
+                    Description = CASE
+                        {descriptionCases}
+                    END
+                WHERE Id IN ({eventIds})";
+
+            await unitWork.ExecuteSqlAsync<Nsap4SettlementContext>(sql);
+        }
