+                CalculationJobRunId = Guid.NewGuid().ToString()
+            };
+            penaltyLedgers.Add(ledgerEntry);
+        }
+        
+        /// <summary>
+        /// 重新计算指定订单的历史罚息（带调整）
+        /// </summary>
+        /// <param name="plugins">包含调整信息的订单插件列表</param>
+        public async Task RecalculateHistoricalOverdueAsync(List<SaleOrderPlugin> plugins)
+        {
+            if (plugins == null || !plugins.Any()) return;
+
+            var orderIds = plugins.Select(p => p.DocEntry).Distinct().ToList();
+            
+            // 1. 获取ORDR实体
+            var orders = await UnitWork.Find<ORDR>(o => orderIds.Contains(o.DocEntry)).ToListAsync();
+            
+            // 2. 批量预加载数据
+            var customerTypes = await _customerCommonApp.GetMainlandCustomerType();
+            var penaltyRuleSchool = await GetApplicablePenaltyRule(true);
+            var penaltyRuleOther = await GetApplicablePenaltyRule(false);
+            var penaltyRules = new Dictionary<bool, PenaltyRuleDefinition>
+            {
+                { true, penaltyRuleSchool },
+                { false, penaltyRuleOther }
+            };
+            
+            var batchSaleOrders = await _historicalOverdueCalculationService.GetBatchSaleOrdersAsync(orderIds);
+            
+            var groupNums = batchSaleOrders.Values
+                .Where(o => o != null && o.GroupNum.HasValue)
+                .Select(o => o.GroupNum.Value)
+                .Distinct()
+                .ToList();
+            var batchPayTerms = await _historicalOverdueCalculationService.GetBatchPayTermsAsync(groupNums);
+            
+            var batchDeliveries = await _historicalOverdueCalculationService.GetBatchAlreadyDeliverysAsync(orderIds);
+            var batchReceipts = await GetBatchReceiptHistoryAsync(orderIds);
+            
+            // 计算截止日期为今天
+            var endDate = DateTime.Now.Date;
+            var batchReturns = await _historicalOverdueCalculationService.GetBatchHistoricalReturnsAsync(orderIds, endDate);
+            var batchRefunds = await GetBatchRefundHistoryAsync(orderIds);
+            var batchClearRecons = await GetBatchHistoricalClearReconsInternal(UnitWork, orderIds);
+
+            // 插件数据直接使用传入的，不需要查库
+            var batchSaleOrderPlugins = plugins.ToDictionary(p => p.DocEntry, p => p);
+            
+            var slpCodes = orders.Where(o => o.SlpCode.HasValue)
+                .Select(o => o.SlpCode.Value)
+                .Distinct()
+                .ToList();
+            var batchSlps = await GetBatchSlpsAsync(slpCodes);
+
+
+            //10. 提取所有相关订单的插件的关联备注（【可清单】和不可清单）
+            var batchSaleOrderRemarkCanClear = await UnitWork.Find<SaleOrdrRemark>(r =>
+                orderIds.Contains(r.DocEntry) &&
+                r.SboId == SboIdEnums.neware_201304 &&
+                r.Remark.Contains("【可清单】"))
+                .ToListAsync();
+
+            var batchSaleOrderRemarkCannotClear = await UnitWork.Find<SaleOrdrRemark>(r =>
+                orderIds.Contains(r.DocEntry) &&
+                r.SboId == SboIdEnums.neware_201304 &&
+                r.Remark.Contains("不可清单"))
+                .ToListAsync();
+
+            // 判断是否应该截止计算：只有当【可清单】比不可清单晚时才截止
+            var remarkDic = new Dictionary<int, SaleOrdrRemark>();
+            var canClearDict = batchSaleOrderRemarkCanClear.GroupBy(x => x.DocEntry).ToDictionary(g => g.Key, g => g.OrderByDescending(x => x.CreateDate).First());
+            var cannotClearDict = batchSaleOrderRemarkCannotClear.GroupBy(x => x.DocEntry).ToDictionary(g => g.Key, g => g.OrderByDescending(x => x.CreateDate).First());
+
+            foreach (var orderId in orderIds)
+            {
+                var hasCanClear = canClearDict.TryGetValue(orderId, out var canClearRemark);
+                var hasCannotClear = cannotClearDict.TryGetValue(orderId, out var cannotClearRemark);
+
+                if ((hasCanClear && !hasCannotClear) || (hasCanClear && hasCannotClear && canClearRemark.CreateDate > cannotClearRemark.CreateDate))
+                {
+                    // 只有【可清单】，使用它.
+                    // 两者都有，比较创建时间
+                    // 【可清单】更晚，使用它（截止计算）
+                    remarkDic[orderId] = canClearRemark;
+                }
+                // 如果不可清单更晚，不添加到remarkDic（不截止）
+                // 如果只有不可清单或都没有，不添加到remarkDic
+            }
+            // 3. 处理每个订单
+            foreach (var order in orders)
+            {
+                // 删除旧数据
+                await DeletePenaltyData(order.DocEntry);
+                
+                // 重新计算并导入
+                // 注意：ProcessSingleOrder的第二个参数是calculationDate，这里用Today
+                await ProcessSingleOrder(
+                    order,
+                    endDate,
+                    null,
+                    customerTypes,
+                    penaltyRules,
+                    batchSaleOrders,
+                    batchPayTerms,
+                    batchDeliveries,
+                    batchReceipts,
+                    batchReturns,
+                    batchRefunds,
+                    batchClearRecons,
+                    batchSaleOrderPlugins,
+                    batchSlps,
+                    remarkDic
+                );
+
+                // 更新罚息调整标记
+                batchSaleOrderPlugins.TryGetValue(order.DocEntry, out SaleOrderPlugin plugin);
+                if (plugin != null)
+                {
+                    await UnitWork.UpdateAsync<SaleOrderPlugin>(p => p.Id == plugin.Id, 
+                    p => new SaleOrderPlugin { IsPenaltyAdjusted = true });
+                }
+            }
+
+            await UnitWork.SaveAsync();
+        }
+
+        /// <summary>
+        /// 删除指定订单的罚息数据
+        /// </summary>
+        private async Task DeletePenaltyData(int orderId)
+        {
+            var strOrderId = orderId.ToString();
+            // 查找关联的PenaltyEvent
+            var events = await UnitWork.Find<PenaltyEvent>(e => e.TriggerDocEntry == strOrderId && e.TriggerDocType == "ORDR" && (e.RuleDefinitionId == 8 || e.RuleDefinitionId == 11))
+                .ToListAsync();
+
+            var eventIds = events.Select(x => x.Id).ToList();
+            var ledgers = await UnitWork.Find<PenaltyLedger>(e => eventIds.Contains(e.EventId)).ToListAsync();
+
+            if (events.Any())
+            {
+                // 删除关联的PenaltyLedger
+                await UnitWork.BatchDeleteAsync<PenaltyLedger>(ledgers.ToArray());
+                await UnitWork.SaveAsync();
+                // 删除PenaltyEvent
+                await UnitWork.BatchDeleteAsync<PenaltyEvent>(events.ToArray());
+                
+                await UnitWork.SaveAsync();
+            }
+        }
+
