+        {
+            /// <summary>
+            /// 总批次数量
+            /// </summary>
+            public int TotalBatches { get; set; }
+
+            /// <summary>
+            /// 成功处理批次数量
+            /// </summary>
+            public int SuccessBatches { get; set; }
+
+            /// <summary>
+            /// 失败批次数量
+            /// </summary>
+            public int FailedBatches { get; set; }
+
+            /// <summary>
+            /// 总订单数量
+            /// </summary>
+            public int TotalOrders { get; set; }
+
+            /// <summary>
+            /// 成功处理订单数量
+            /// </summary>
+            public int SuccessOrders { get; set; }
+
+            /// <summary>
+            /// 失败订单数量
+            /// </summary>
+            public int FailedOrders { get; set; }
+
+            /// <summary>
+            /// 总耗时（毫秒）
+            /// </summary>
+            public long TotalMilliseconds { get; set; }
+
+            /// <summary>
+            /// 失败的批次信息列表
+            /// </summary>
+            public List<string> FailedBatchInfo { get; set; } = new List<string>();
+
+            /// <summary>
+            /// 获取吞吐量（订单/秒）
+            /// </summary>
+            public double GetThroughputPerSecond()
+            {
+                return TotalMilliseconds > 0 ? SuccessOrders * 1000.0 / TotalMilliseconds : 0;
+            }
+
+            /// <summary>
+            /// 获取成功率百分比
+            /// </summary>
+            public double GetSuccessRate()
+            {
+                return TotalOrders > 0 ? SuccessOrders * 100.0 / TotalOrders : 0;
+            }
+        }
+    }
